<template><aside class="side"><header><div><b>Workshop job charge</b><small>Attach parts and labor to the till</small></div><span>{{ jobs.length }} OPEN</span></header><label>Job card<select v-model="selected"><option value="">Choose an active job</option><option v-for="job in jobs" :key="job.id" :value="job.id">{{ job.number }} · {{ job.registration }} · {{ job.customer }}</option></select></label><template v-if="job"><div class="summary"><strong>{{ job.vehicle }}</strong><span>{{ job.issue }}</span><small>Current estimate: KES {{ (Number(job.parts||0)+Number(job.labor||0)).toLocaleString() }}</small></div><label>Charge type<select v-model="kind"><option value="parts">Parts</option><option value="labor">Labor</option></select></label><label>Description<input v-model.trim="description" :placeholder="kind==='parts'?'Part / material':'Work performed'" /></label><label>Amount (KES)<input v-model.number="amount" min="0" type="number" /></label><button class="add" :disabled="!description||Number(amount)<=0" @click="addCharge">Add to checkout</button></template><p v-else class="empty">Create or select an active job card to add a workshop charge.</p></aside></template>
<script setup>
import { computed, ref } from 'vue'
const jobs=ref([]);try{jobs.value=JSON.parse(localStorage.getItem('pos.garage.jobs')||'[]').filter(j=>j.status!=='Collected')}catch{}
const selected=ref(''),kind=ref('parts'),description=ref(''),amount=ref(0)
const job=computed(()=>jobs.value.find(j=>j.id===selected.value))
function addCharge(){if(!job.value||!description.value||Number(amount.value)<=0)return;const item={id:`garage-${Date.now()}`,name:`${job.value.number} · ${kind.value==='parts'?'Part':'Labor'} · ${description.value}`,sku:`GARAGE-${kind.value.toUpperCase()}`,price_minor:Math.round(Number(amount.value)*100),unit_price_minor:Math.round(Number(amount.value)*100),quantity:1,kind:'service',job_card_id:job.value.id};window.dispatchEvent(new CustomEvent('pos:add-item',{detail:item}));window.dispatchEvent(new CustomEvent('pos:notification',{detail:{message:`Added ${kind.value} charge to checkout`,type:'success'}}));description.value='';amount.value=0}
</script>
<style scoped>
.side{display:grid;gap:11px;padding:15px;border:1px solid #e1e5eb;border-radius:12px;background:#fff}.side header{display:flex;align-items:center;justify-content:space-between;padding-bottom:10px;border-bottom:1px solid #edf0f3}.side header div{display:grid;gap:4px}.side header b{font-size:13px;color:#202d43}.side header small,.summary span,.summary small{color:#6e7887;font-size:10px}.side header span{padding:4px 7px;border-radius:5px;background:#eef2f8;color:#35517f;font-size:9px;font-weight:800}.side>label{display:grid;gap:5px;color:#586376;font-size:10px;font-weight:700}.side select,.side input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d5dbe4;border-radius:6px;background:white}.summary{display:grid;gap:5px;padding:10px;border-radius:7px;background:#f5f7fa}.summary strong{font-size:12px}.add{padding:10px;border:0;border-radius:7px;background:#355fa0;color:#fff;font-weight:700;cursor:pointer}.add:disabled{opacity:.5;cursor:not-allowed}.empty{margin:0;color:#7b8594;font-size:11px;line-height:1.5}
</style>
